----------------------------------------------------IT Operations Maturity - ALL TABLES, consolidated from-scratch build----------------------------------------------
-- Generated by re-deriving every column from the CURRENT, live source of truth:
--   GAVS.AllocationSystem.Model/CSP/Tables/ITOPS_MATURITY.cs
--   GAVS.AllocationSystem.Model/CSP/Tables/ITOPS_REPORTS.cs
-- cross-checked TWICE against the original DDL (V2_02_CreateTables.sql /
-- V2_02b_RecreateReportTables.sql) and every column-level ALTER that ran on
-- top of it since (V2_11, V2_12, V2_14, V2_15, V2_16, V2_17). This single
-- script produces EXACTLY the schema those incremental scripts leave behind
-- today - it is a REPLACEMENT for running V2_02 + V2_02b + V2_11 + V2_12 +
-- V2_14 + V2_15 + V2_16 + V2_17 individually, not an addition to them.
--
-- Deliberately excludes what those incremental scripts only existed to undo
-- or backfill:
--   - IS_PRIMARY on ASSESSOR/REVIEWER (V2_02 created it, V2_14 dropped it -
--     never created here at all)
--   - ITOPS_EVIDENCE's old FILE_NAME/STORAGE_PATH/CONTENT_TYPE/FILE_SIZE_BYTES
--     columns (V2_02 created them, V2_17 dropped them in favour of
--     FILE_DATA_ID - never created here at all)
--   - ITOPS_ROLE_ASSIGNMENT.SCOPE_TYPE is created NOT NULL directly (V2_16
--     had to add it nullable, backfill, then tighten - not needed from empty)
--
-- Run ONCE against a fresh/restored database that has never had any ITOPS_*
-- table. Idempotent in the sense that it drops-and-recreates its own tables
-- first (safe to re-run after a partial failure) - but note that means EVERY
-- ITOPS_* table's data is wiped on every run. Do not run this against an
-- environment with real assessment data you want to keep.
--
-- FK targets for cross-schema references (same physical DB, per V2_02's own
-- header note):
--   EMP_INFO(EMP_ID) - VARCHAR(50), not VARCHAR(10) - every FK column below
--                      matches that exactly.
--   PROJECT(PROJ_ID) - existing core CSM project master.

IF OBJECT_ID('ITOPS_NOTIFICATION', 'U') IS NOT NULL DROP TABLE ITOPS_NOTIFICATION;
IF OBJECT_ID('ITOPS_FINDING_ACTIVITY', 'U') IS NOT NULL DROP TABLE ITOPS_FINDING_ACTIVITY;
IF OBJECT_ID('ITOPS_FINDING', 'U') IS NOT NULL DROP TABLE ITOPS_FINDING;
IF OBJECT_ID('ITOPS_EVIDENCE', 'U') IS NOT NULL DROP TABLE ITOPS_EVIDENCE;
IF OBJECT_ID('ITOPS_SCORE', 'U') IS NOT NULL DROP TABLE ITOPS_SCORE;
IF OBJECT_ID('ITOPS_ASSESSMENT_ASSESSEE', 'U') IS NOT NULL DROP TABLE ITOPS_ASSESSMENT_ASSESSEE;
IF OBJECT_ID('ITOPS_ASSESSMENT_REVIEWER', 'U') IS NOT NULL DROP TABLE ITOPS_ASSESSMENT_REVIEWER;
IF OBJECT_ID('ITOPS_ASSESSMENT_ASSESSOR', 'U') IS NOT NULL DROP TABLE ITOPS_ASSESSMENT_ASSESSOR;
IF OBJECT_ID('ITOPS_ASSESSMENT', 'U') IS NOT NULL DROP TABLE ITOPS_ASSESSMENT;
IF OBJECT_ID('ITOPS_ASSESSMENT_MASTER', 'U') IS NOT NULL DROP TABLE ITOPS_ASSESSMENT_MASTER;
IF OBJECT_ID('ITOPS_DOMAIN_PROJECT_MAP_AUDIT', 'U') IS NOT NULL DROP TABLE ITOPS_DOMAIN_PROJECT_MAP_AUDIT;
IF OBJECT_ID('ITOPS_PROJECT_ASSESSEE', 'U') IS NOT NULL DROP TABLE ITOPS_PROJECT_ASSESSEE;
IF OBJECT_ID('ITOPS_DOMAIN_PROJECT_MAP', 'U') IS NOT NULL DROP TABLE ITOPS_DOMAIN_PROJECT_MAP;
IF OBJECT_ID('ITOPS_ROLE_ASSIGNMENT', 'U') IS NOT NULL DROP TABLE ITOPS_ROLE_ASSIGNMENT;
IF OBJECT_ID('ITOPS_ROLE', 'U') IS NOT NULL DROP TABLE ITOPS_ROLE;
IF OBJECT_ID('ITOPS_PARAMETER_LEVEL', 'U') IS NOT NULL DROP TABLE ITOPS_PARAMETER_LEVEL;
IF OBJECT_ID('ITOPS_PARAMETER', 'U') IS NOT NULL DROP TABLE ITOPS_PARAMETER;
IF OBJECT_ID('ITOPS_CATEGORY', 'U') IS NOT NULL DROP TABLE ITOPS_CATEGORY;
IF OBJECT_ID('ITOPS_DOMAIN', 'U') IS NOT NULL DROP TABLE ITOPS_DOMAIN;
IF OBJECT_ID('ITOPS_REPORT_PARAMS', 'U') IS NOT NULL DROP TABLE ITOPS_REPORT_PARAMS;
IF OBJECT_ID('ITOPS_REPORT_SP_DETAILS', 'U') IS NOT NULL DROP TABLE ITOPS_REPORT_SP_DETAILS;
GO

----------------------------------------------------Master data----------------------------------------------

CREATE TABLE ITOPS_DOMAIN (
    ID INT NOT NULL IDENTITY(1,1) PRIMARY KEY,
    NAME VARCHAR(150) NOT NULL,
    DESCRIPTION VARCHAR(500) NULL,
    MIN_REQUIRED_SCORE INT NULL,
    DISPLAY_ORDER INT NOT NULL DEFAULT 0,
    CODE VARCHAR(50) NULL,
    DEFAULT_ASSESSOR_ID VARCHAR(50) NULL,
    DEFAULT_REVIEWER_ID VARCHAR(50) NULL,
    CREATED_BY VARCHAR(10), CREATED_DATE DATETIME,
    UPDATED_BY VARCHAR(10), UPDATED_DATE DATETIME,
    ISACTIVE BIT,
    CONSTRAINT FK_ITOPS_DOMAIN_DEFAULT_ASSESSOR FOREIGN KEY (DEFAULT_ASSESSOR_ID) REFERENCES EMP_INFO(EMP_ID),
    CONSTRAINT FK_ITOPS_DOMAIN_DEFAULT_REVIEWER FOREIGN KEY (DEFAULT_REVIEWER_ID) REFERENCES EMP_INFO(EMP_ID)
);
CREATE UNIQUE INDEX UQ_ITOPS_DOMAIN_CODE ON ITOPS_DOMAIN(CODE) WHERE CODE IS NOT NULL;
GO

CREATE TABLE ITOPS_CATEGORY (
    ID INT NOT NULL IDENTITY(1,1) PRIMARY KEY,
    DOMAIN_ID INT NOT NULL,
    NAME VARCHAR(150) NOT NULL,
    DISPLAY_ORDER INT NOT NULL DEFAULT 0,
    START_DATE DATE NOT NULL,
    END_DATE DATE NULL,
    -- Which cloud provider ("Azure"/"AWS"/"GCP") this category belongs to - NULL for every
    -- non-Cloud domain's categories. See V2_30_CloudProvider.sql.
    PROVIDER VARCHAR(20) NULL,
    CREATED_BY VARCHAR(10), CREATED_DATE DATETIME,
    UPDATED_BY VARCHAR(10), UPDATED_DATE DATETIME,
    ISACTIVE BIT,
    CONSTRAINT FK_ITOPS_CATEGORY_DOMAIN FOREIGN KEY (DOMAIN_ID) REFERENCES ITOPS_DOMAIN(ID),
    CONSTRAINT CK_ITOPS_CATEGORY_DATES CHECK (END_DATE IS NULL OR END_DATE > START_DATE)
);
GO

CREATE TABLE ITOPS_PARAMETER (
    ID INT NOT NULL IDENTITY(1,1) PRIMARY KEY,
    CATEGORY_ID INT NOT NULL,
    NAME VARCHAR(250) NOT NULL,
    DEFINITION VARCHAR(2000) NULL,
    MIN_REQUIRED_SCORE INT NULL,
    DISPLAY_ORDER INT NOT NULL DEFAULT 0,
    START_DATE DATE NOT NULL,
    END_DATE DATE NULL,
    CREATED_BY VARCHAR(10), CREATED_DATE DATETIME,
    UPDATED_BY VARCHAR(10), UPDATED_DATE DATETIME,
    ISACTIVE BIT,
    CONSTRAINT FK_ITOPS_PARAMETER_CATEGORY FOREIGN KEY (CATEGORY_ID) REFERENCES ITOPS_CATEGORY(ID),
    CONSTRAINT CK_ITOPS_PARAMETER_DATES CHECK (END_DATE IS NULL OR END_DATE > START_DATE)
);
GO

-- No audit/ISACTIVE columns - ITOPS_PARAMETER_LEVEL does NOT derive from
-- EntityBase in the C# model, so none are mapped/queried against this table.
CREATE TABLE ITOPS_PARAMETER_LEVEL (
    ID INT NOT NULL IDENTITY(1,1) PRIMARY KEY,
    PARAMETER_ID INT NOT NULL,
    LEVEL_NO TINYINT NOT NULL,
    DESCRIPTION VARCHAR(2000) NULL,
    CONSTRAINT FK_ITOPS_PARAMETER_LEVEL_PARAMETER FOREIGN KEY (PARAMETER_ID) REFERENCES ITOPS_PARAMETER(ID),
    CONSTRAINT UQ_ITOPS_PARAMETER_LEVEL UNIQUE (PARAMETER_ID, LEVEL_NO),
    CONSTRAINT CK_ITOPS_PARAMETER_LEVEL_NO CHECK (LEVEL_NO BETWEEN 1 AND 5)
);
GO

CREATE TABLE ITOPS_ROLE (
    ID INT NOT NULL IDENTITY(1,1) PRIMARY KEY,
    ROLE_CODE VARCHAR(50) NOT NULL,
    ROLE_NAME VARCHAR(150) NOT NULL,
    DESCRIPTION VARCHAR(500) NULL,
    CREATED_BY VARCHAR(10), CREATED_DATE DATETIME,
    UPDATED_BY VARCHAR(10), UPDATED_DATE DATETIME,
    ISACTIVE BIT
);
CREATE UNIQUE INDEX UQ_ITOPS_ROLE_CODE ON ITOPS_ROLE(ROLE_CODE);
GO

-- SCOPE_TYPE created NOT NULL directly (no ORG/OWN/PROJECT backfill needed on
-- an empty table) - 'ORG' | 'OWN' | 'PROJECT', see V2_16's header for the
-- full semantics of each value.
CREATE TABLE ITOPS_ROLE_ASSIGNMENT (
    ID INT NOT NULL IDENTITY(1,1) PRIMARY KEY,
    ROLE_ID INT NOT NULL,
    EMP_ID VARCHAR(50) NOT NULL,
    PROJECT_ID VARCHAR(20) NULL,  -- null = role applies org-wide or to the employee's own CSM project access (see SCOPE_TYPE); set = scoped to that one project
    SCOPE_TYPE VARCHAR(10) NOT NULL,
    CREATED_BY VARCHAR(10), CREATED_DATE DATETIME,
    UPDATED_BY VARCHAR(10), UPDATED_DATE DATETIME,
    ISACTIVE BIT,
    CONSTRAINT FK_ITOPS_ROLE_ASSIGNMENT_ROLE FOREIGN KEY (ROLE_ID) REFERENCES ITOPS_ROLE(ID),
    CONSTRAINT FK_ITOPS_ROLE_ASSIGNMENT_EMP FOREIGN KEY (EMP_ID) REFERENCES EMP_INFO(EMP_ID),
    CONSTRAINT FK_ITOPS_ROLE_ASSIGNMENT_PROJECT FOREIGN KEY (PROJECT_ID) REFERENCES PROJECT(PROJ_ID)
);
CREATE UNIQUE INDEX UQ_ITOPS_ROLE_ASSIGNMENT ON ITOPS_ROLE_ASSIGNMENT(ROLE_ID, EMP_ID, PROJECT_ID) WHERE ISACTIVE = 1;
GO

CREATE TABLE ITOPS_DOMAIN_PROJECT_MAP (
    ID INT NOT NULL IDENTITY(1,1) PRIMARY KEY,
    DOMAIN_ID INT NOT NULL,
    PROJECT_ID VARCHAR(20) NOT NULL,
    CREATED_BY VARCHAR(10), CREATED_DATE DATETIME,
    UPDATED_BY VARCHAR(10), UPDATED_DATE DATETIME,
    ISACTIVE BIT,
    CONSTRAINT FK_ITOPS_DOMAIN_PROJECT_MAP_DOMAIN FOREIGN KEY (DOMAIN_ID) REFERENCES ITOPS_DOMAIN(ID),
    CONSTRAINT FK_ITOPS_DOMAIN_PROJECT_MAP_PROJECT FOREIGN KEY (PROJECT_ID) REFERENCES PROJECT(PROJ_ID)
);
CREATE UNIQUE INDEX UQ_ITOPS_DOMAIN_PROJECT_MAP ON ITOPS_DOMAIN_PROJECT_MAP(DOMAIN_ID, PROJECT_ID) WHERE ISACTIVE = 1;
GO

-- Standing per-project assessee roster set in Configure Scope. No FK to
-- EMP_INFO (matches the original V2_12 script exactly - only PROJECT is
-- constrained).
CREATE TABLE ITOPS_PROJECT_ASSESSEE (
    ID INT NOT NULL IDENTITY(1,1) PRIMARY KEY,
    PROJECT_ID VARCHAR(20) NOT NULL,
    EMP_ID VARCHAR(50) NOT NULL,
    CREATED_BY VARCHAR(10), CREATED_DATE DATETIME,
    UPDATED_BY VARCHAR(10), UPDATED_DATE DATETIME,
    ISACTIVE BIT,
    CONSTRAINT FK_ITOPS_PROJECT_ASSESSEE_PROJECT FOREIGN KEY (PROJECT_ID) REFERENCES PROJECT(PROJ_ID)
);
CREATE UNIQUE INDEX UQ_ITOPS_PROJECT_ASSESSEE ON ITOPS_PROJECT_ASSESSEE(PROJECT_ID, EMP_ID) WHERE ISACTIVE = 1;
GO

-- Append-only change log for ITOPS_DOMAIN_PROJECT_MAP. NOTIFIED included
-- directly (V2_15's ALTER ADD, folded in here since this is a fresh build).
CREATE TABLE ITOPS_DOMAIN_PROJECT_MAP_AUDIT (
    ID INT NOT NULL IDENTITY(1,1) PRIMARY KEY,
    PROJECT_ID VARCHAR(20) NOT NULL,
    DOMAIN_ID INT NOT NULL,
    ACTION VARCHAR(20) NOT NULL,
    REASON VARCHAR(500) NULL,
    NOTIFIED BIT NOT NULL DEFAULT 0,
    CREATED_BY VARCHAR(10), CREATED_DATE DATETIME,
    UPDATED_BY VARCHAR(10), UPDATED_DATE DATETIME,
    ISACTIVE BIT,
    CONSTRAINT FK_ITOPS_DPM_AUDIT_DOMAIN FOREIGN KEY (DOMAIN_ID) REFERENCES ITOPS_DOMAIN(ID)
);
CREATE INDEX IX_ITOPS_DPM_AUDIT_PROJECT ON ITOPS_DOMAIN_PROJECT_MAP_AUDIT(PROJECT_ID);
GO

----------------------------------------------------Application (transactional) data----------------------------------------------

CREATE TABLE ITOPS_ASSESSMENT_MASTER (
    ID INT NOT NULL IDENTITY(1,1) PRIMARY KEY,
    CYCLE_LABEL VARCHAR(50) NOT NULL,
    START_DATE DATE NOT NULL,
    END_DATE DATE NOT NULL,
    STATUS VARCHAR(20) NOT NULL,
    DESCRIPTION VARCHAR(500) NULL,
    CREATED_BY VARCHAR(10), CREATED_DATE DATETIME,
    UPDATED_BY VARCHAR(10), UPDATED_DATE DATETIME,
    ISACTIVE BIT,
    CONSTRAINT CK_ITOPS_ASSESSMENT_MASTER_DATES CHECK (END_DATE > START_DATE)
);
CREATE UNIQUE INDEX UQ_ITOPS_ASSESSMENT_MASTER_CYCLE ON ITOPS_ASSESSMENT_MASTER(CYCLE_LABEL);
GO

CREATE TABLE ITOPS_ASSESSMENT (
    ID INT NOT NULL IDENTITY(1,1) PRIMARY KEY,
    ASSESSMENT_MASTER_ID INT NOT NULL,
    DOMAIN_ID INT NOT NULL,
    PROJECT_ID VARCHAR(20) NOT NULL,
    BUSINESS_UNIT VARCHAR(150) NULL,
    ACCOUNT_NAME VARCHAR(150) NULL,
    STATUS VARCHAR(30) NOT NULL DEFAULT 'NotStarted',
    SUBMITTED_DATE DATETIME NULL,
    APPROVED_DATE DATETIME NULL,
    RETURN_COMMENT VARCHAR(1000) NULL,
    -- Which cloud provider this Cloud assessment scores - NULL until the Assessor picks
    -- one on first open, then locked. NULL forever for every non-Cloud domain. See
    -- V2_30_CloudProvider.sql.
    CLOUD_PROVIDER VARCHAR(20) NULL,
    CREATED_BY VARCHAR(10), CREATED_DATE DATETIME,
    UPDATED_BY VARCHAR(10), UPDATED_DATE DATETIME,
    ISACTIVE BIT,
    CONSTRAINT FK_ITOPS_ASSESSMENT_MASTER FOREIGN KEY (ASSESSMENT_MASTER_ID) REFERENCES ITOPS_ASSESSMENT_MASTER(ID),
    CONSTRAINT FK_ITOPS_ASSESSMENT_DOMAIN FOREIGN KEY (DOMAIN_ID) REFERENCES ITOPS_DOMAIN(ID),
    CONSTRAINT FK_ITOPS_ASSESSMENT_PROJECT FOREIGN KEY (PROJECT_ID) REFERENCES PROJECT(PROJ_ID)
);
CREATE UNIQUE INDEX UQ_ITOPS_ASSESSMENT ON ITOPS_ASSESSMENT(ASSESSMENT_MASTER_ID, DOMAIN_ID, PROJECT_ID) WHERE ISACTIVE = 1;
GO

-- No IS_PRIMARY - dropped by V2_14, never created here. Every assessor is an
-- equal owner.
CREATE TABLE ITOPS_ASSESSMENT_ASSESSOR (
    ID INT NOT NULL IDENTITY(1,1) PRIMARY KEY,
    ASSESSMENT_ID INT NOT NULL,
    ASSESSOR_EMP_ID VARCHAR(50) NOT NULL,
    CREATED_BY VARCHAR(10), CREATED_DATE DATETIME,
    UPDATED_BY VARCHAR(10), UPDATED_DATE DATETIME,
    ISACTIVE BIT,
    CONSTRAINT FK_ITOPS_ASSESSMENT_ASSESSOR_ASSESSMENT FOREIGN KEY (ASSESSMENT_ID) REFERENCES ITOPS_ASSESSMENT(ID),
    CONSTRAINT FK_ITOPS_ASSESSMENT_ASSESSOR_EMP FOREIGN KEY (ASSESSOR_EMP_ID) REFERENCES EMP_INFO(EMP_ID)
);
CREATE UNIQUE INDEX UQ_ITOPS_ASSESSMENT_ASSESSOR ON ITOPS_ASSESSMENT_ASSESSOR(ASSESSMENT_ID, ASSESSOR_EMP_ID) WHERE ISACTIVE = 1;
GO

-- No IS_PRIMARY - see ITOPS_ASSESSMENT_ASSESSOR above.
CREATE TABLE ITOPS_ASSESSMENT_REVIEWER (
    ID INT NOT NULL IDENTITY(1,1) PRIMARY KEY,
    ASSESSMENT_ID INT NOT NULL,
    REVIEWER_EMP_ID VARCHAR(50) NOT NULL,
    CREATED_BY VARCHAR(10), CREATED_DATE DATETIME,
    UPDATED_BY VARCHAR(10), UPDATED_DATE DATETIME,
    ISACTIVE BIT,
    CONSTRAINT FK_ITOPS_ASSESSMENT_REVIEWER_ASSESSMENT FOREIGN KEY (ASSESSMENT_ID) REFERENCES ITOPS_ASSESSMENT(ID),
    CONSTRAINT FK_ITOPS_ASSESSMENT_REVIEWER_EMP FOREIGN KEY (REVIEWER_EMP_ID) REFERENCES EMP_INFO(EMP_ID)
);
CREATE UNIQUE INDEX UQ_ITOPS_ASSESSMENT_REVIEWER ON ITOPS_ASSESSMENT_REVIEWER(ASSESSMENT_ID, REVIEWER_EMP_ID) WHERE ISACTIVE = 1;
GO

CREATE TABLE ITOPS_ASSESSMENT_ASSESSEE (
    ID INT NOT NULL IDENTITY(1,1) PRIMARY KEY,
    ASSESSMENT_ID INT NOT NULL,
    ASSESSEE_EMP_ID VARCHAR(50) NOT NULL,
    CREATED_BY VARCHAR(10), CREATED_DATE DATETIME,
    UPDATED_BY VARCHAR(10), UPDATED_DATE DATETIME,
    ISACTIVE BIT,
    CONSTRAINT FK_ITOPS_ASSESSMENT_ASSESSEE_ASSESSMENT FOREIGN KEY (ASSESSMENT_ID) REFERENCES ITOPS_ASSESSMENT(ID),
    CONSTRAINT FK_ITOPS_ASSESSMENT_ASSESSEE_EMP FOREIGN KEY (ASSESSEE_EMP_ID) REFERENCES EMP_INFO(EMP_ID)
);
CREATE UNIQUE INDEX UQ_ITOPS_ASSESSMENT_ASSESSEE ON ITOPS_ASSESSMENT_ASSESSEE(ASSESSMENT_ID, ASSESSEE_EMP_ID) WHERE ISACTIVE = 1;
GO

CREATE TABLE ITOPS_SCORE (
    ID INT NOT NULL IDENTITY(1,1) PRIMARY KEY,
    ASSESSMENT_ID INT NOT NULL,
    PARAMETER_ID INT NOT NULL,
    SCORE_VALUE INT NULL,          -- NULL = "NA"; else 1-5
    NOTES VARCHAR(2000) NOT NULL,
    IS_IMPROVEMENT_AREA BIT NOT NULL DEFAULT 0,
    IMPROVEMENT_STATUS VARCHAR(20) NULL,
    REJECTION_JUSTIFICATION VARCHAR(1000) NULL,
    CREATED_BY VARCHAR(10), CREATED_DATE DATETIME,
    UPDATED_BY VARCHAR(10), UPDATED_DATE DATETIME,
    ISACTIVE BIT,
    CONSTRAINT FK_ITOPS_SCORE_ASSESSMENT FOREIGN KEY (ASSESSMENT_ID) REFERENCES ITOPS_ASSESSMENT(ID),
    CONSTRAINT FK_ITOPS_SCORE_PARAMETER FOREIGN KEY (PARAMETER_ID) REFERENCES ITOPS_PARAMETER(ID)
);
CREATE UNIQUE INDEX UQ_ITOPS_SCORE ON ITOPS_SCORE(ASSESSMENT_ID, PARAMETER_ID) WHERE ISACTIVE = 1;
GO

-- FILE_DATA_ID only (V2_17) - evidence files live in the shared FILE_DATA
-- table (Cldb.FILE_DATA), soft cross-database reference, no real FK, same
-- convention as every other Cldb reference from an ITOPS table.
CREATE TABLE ITOPS_EVIDENCE (
    ID INT NOT NULL IDENTITY(1,1) PRIMARY KEY,
    SCORE_ID INT NOT NULL,
    FILE_DATA_ID INT NOT NULL,
    CREATED_BY VARCHAR(10), CREATED_DATE DATETIME,
    UPDATED_BY VARCHAR(10), UPDATED_DATE DATETIME,
    ISACTIVE BIT,
    CONSTRAINT FK_ITOPS_EVIDENCE_SCORE FOREIGN KEY (SCORE_ID) REFERENCES ITOPS_SCORE(ID)
);
GO

CREATE TABLE ITOPS_FINDING (
    ID INT NOT NULL IDENTITY(1,1) PRIMARY KEY,
    SCORE_ID INT NOT NULL,
    GAP INT NOT NULL,
    RECOMMENDED_ACTION VARCHAR(2000) NULL,
    STATUS VARCHAR(20) NOT NULL DEFAULT 'Open',
    ASSESSEE_EMP_ID VARCHAR(50) NULL,
    TARGET_DATE DATE NULL,
    REVISED_TARGET_DATE DATE NULL,
    RETARGET_APPROVED_BY VARCHAR(50) NULL,
    RETARGET_REASON VARCHAR(1000) NULL,
    ACTION_TAKEN VARCHAR(2000) NULL,
    REJECTION_COMMENT VARCHAR(1000) NULL,
    LAST_MANAGEMENT_UPDATE DATETIME NULL,
    CLOSED_DATE DATETIME NULL,
    CREATED_BY VARCHAR(10), CREATED_DATE DATETIME,
    UPDATED_BY VARCHAR(10), UPDATED_DATE DATETIME,
    ISACTIVE BIT,
    CONSTRAINT FK_ITOPS_FINDING_SCORE FOREIGN KEY (SCORE_ID) REFERENCES ITOPS_SCORE(ID),
    CONSTRAINT FK_ITOPS_FINDING_ASSESSEE FOREIGN KEY (ASSESSEE_EMP_ID) REFERENCES EMP_INFO(EMP_ID),
    CONSTRAINT FK_ITOPS_FINDING_RETARGET_APPROVER FOREIGN KEY (RETARGET_APPROVED_BY) REFERENCES EMP_INFO(EMP_ID)
);
GO

CREATE TABLE ITOPS_FINDING_ACTIVITY (
    ID INT NOT NULL IDENTITY(1,1) PRIMARY KEY,
    FINDING_ID INT NOT NULL,
    ACTIVITY_TYPE VARCHAR(30) NOT NULL,
    COMMENTS VARCHAR(1000) NULL,
    FROM_EMP_ID VARCHAR(50) NULL,
    TO_EMP_ID VARCHAR(50) NULL,
    CREATED_BY VARCHAR(10), CREATED_DATE DATETIME,
    UPDATED_BY VARCHAR(10), UPDATED_DATE DATETIME,
    ISACTIVE BIT,
    CONSTRAINT FK_ITOPS_FINDING_ACTIVITY_FINDING FOREIGN KEY (FINDING_ID) REFERENCES ITOPS_FINDING(ID),
    CONSTRAINT FK_ITOPS_FINDING_ACTIVITY_FROM FOREIGN KEY (FROM_EMP_ID) REFERENCES EMP_INFO(EMP_ID),
    CONSTRAINT FK_ITOPS_FINDING_ACTIVITY_TO FOREIGN KEY (TO_EMP_ID) REFERENCES EMP_INFO(EMP_ID)
);
GO

CREATE TABLE ITOPS_NOTIFICATION (
    ID INT NOT NULL IDENTITY(1,1) PRIMARY KEY,
    NOTIFICATION_TYPE VARCHAR(50) NOT NULL,
    ASSESSMENT_ID INT NULL,
    FINDING_ID INT NULL,
    RECIPIENT_EMP_ID VARCHAR(50) NOT NULL,
    MESSAGE VARCHAR(1000) NOT NULL,
    IS_SENT BIT NOT NULL DEFAULT 0,
    SENT_DATE DATETIME NULL,
    CREATED_BY VARCHAR(10), CREATED_DATE DATETIME,
    UPDATED_BY VARCHAR(10), UPDATED_DATE DATETIME,
    ISACTIVE BIT,
    CONSTRAINT FK_ITOPS_NOTIFICATION_ASSESSMENT FOREIGN KEY (ASSESSMENT_ID) REFERENCES ITOPS_ASSESSMENT(ID),
    CONSTRAINT FK_ITOPS_NOTIFICATION_FINDING FOREIGN KEY (FINDING_ID) REFERENCES ITOPS_FINDING(ID),
    CONSTRAINT FK_ITOPS_NOTIFICATION_RECIPIENT FOREIGN KEY (RECIPIENT_EMP_ID) REFERENCES EMP_INFO(EMP_ID),
    CONSTRAINT CK_ITOPS_NOTIFICATION_TARGET CHECK (
        (ASSESSMENT_ID IS NOT NULL AND FINDING_ID IS NULL) OR
        (ASSESSMENT_ID IS NULL AND FINDING_ID IS NOT NULL)
    )
);
GO

----------------------------------------------------Report registration (module-local copy - unused, kept for schema parity only)----------------------------------------------
-- NOTE: the app actually reads the SHARED REPORTS_SP_DETAILS/REPORTS_PARAMS
-- tables (see ITOperationMaturity_Report_SP.sql's own header) - these two
-- tables are not queried anywhere in the current codebase. Included only so
-- the schema matches the ERD/model exactly; safe to skip if you'd rather not
-- carry dead objects into UAT.

CREATE TABLE ITOPS_REPORT_SP_DETAILS (
    ID INT NOT NULL IDENTITY(1,1) PRIMARY KEY,
    SP_NAME VARCHAR(200) NOT NULL,
    SP_DISPLAY_NAME VARCHAR(200) NOT NULL,
    DB_NAME VARCHAR(50) NULL
);
GO

CREATE TABLE ITOPS_REPORT_PARAMS (
    ID INT NOT NULL IDENTITY(1,1) PRIMARY KEY,
    REPORT_SP_ID INT NOT NULL,
    PARAM_NAME VARCHAR(100) NOT NULL,
    PARAM_TYPE VARCHAR(50) NULL,
    PARAM_VALUE VARCHAR(200) NULL,
    CONSTRAINT FK_ITOPS_REPORT_PARAMS_SP FOREIGN KEY (REPORT_SP_ID) REFERENCES ITOPS_REPORT_SP_DETAILS(ID)
);
GO
